"use client";

/**
 * Onboarding film: a welcome headline, three steps (a pointer working
 * through settings, a screen recording, a checklist ticking itself off),
 * a ring that fills to show setup is done, then the end card. About 30
 * seconds at 1920 by 1080. Every scene is a Better Design video component,
 * cut together with the whip pan transition.
 *
 * Written by Better Design.
 */
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import { Easing } from "remotion";
import { CursorPath } from "@/components/bd-video/cursor-path";
import { EndCard } from "@/components/bd-video/end-card";
import { HeadlineReveal } from "@/components/bd-video/headline-reveal";
import { RecordingShot } from "@/components/bd-video/recording-shot";
import { RingMeter } from "@/components/bd-video/ring-meter";
import { WordRotate } from "@/components/bd-video/word-rotate";
import { whipPan } from "@/components/bd-video/transition-whip-pan";
import { type VideoTheme, VideoThemeProvider } from "@/lib/bd-video";

/** Every piece of copy, picture and number the onboarding film shows. */
export interface OnboardingFilmContent {
  /** The welcome headline. Keep it to one or two lines. */
  welcome: string;
  /** Step one: the labels on the settings card the pointer works through. */
  settings: { heading: string; toggleLabel: string; buttonLabel: string; savedLabel: string };
  /** Step two: a screen recording (.mp4, .webm, .mov) or a still. A placeholder page is drawn when unset. */
  recording?: string;
  /** The capture's pixel size, as ffprobe reports it. */
  recordingSize: { width: number; height: number };
  /** Step three: the words before the checklist, and one item per box. The last one stays. */
  checklistPrefix: string;
  checklist: string[];
  /** Done: the share the ring fills to, 0 to 100, and what it is a share of. `source` records where the figure comes from; it is not drawn. */
  done: { value: number; caption: string; source: string };
  /** The product name on the end card. */
  name: string;
  /** The call to action on the end card button. */
  cta: string;
  /** The web address under the button. */
  url: string;
}

const DEFAULT_CONTENT: OnboardingFilmContent = {
  welcome: "Welcome. Let's get you set up.",
  settings: { heading: "Notifications", toggleLabel: "Weekly summary", buttonLabel: "Save changes", savedLabel: "Saved" },
  recordingSize: { width: 1440, height: 900 },
  checklistPrefix: "Next, add your",
  checklist: ["team", "projects", "first file"],
  done: { value: 100, caption: "of your setup is complete", source: "Setup steps finished, out of the steps shown" },
  name: "Your product",
  cta: "Open your workspace",
  url: "yourproduct.com",
};

export interface OnboardingFilmProps {
  content?: Partial<OnboardingFilmContent>;
  theme?: Partial<VideoTheme>;
}

/** Frames per scene, in order: welcome, settings, recording, checklist, done, end. */
const SCENES = [135, 150, 180, 180, 150, 170] as const;
const CUT = 15;
const cut = () => <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: CUT, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />;

/** An onboarding film built from Better Design video components. */
export function OnboardingFilm({ content, theme }: OnboardingFilmProps) {
  const c = { ...DEFAULT_CONTENT, ...content };
  const settings = { ...DEFAULT_CONTENT.settings, ...content?.settings };
  const done = { ...DEFAULT_CONTENT.done, ...content?.done };
  return (
    <VideoThemeProvider theme={theme}>
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENES[0]}>
          <HeadlineReveal text={c.welcome} variant="words" theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[1]}>
          <CursorPath
            points={[
              { x: 0.3, y: 0.82, at: 15 },
              { x: 0.64, y: 0.5, at: 50, click: true },
              { x: 0.58, y: 0.63, at: 90, click: true },
              { x: 0.68, y: 0.74, at: 125 },
            ]}
            heading={settings.heading}
            toggleLabel={settings.toggleLabel}
            buttonLabel={settings.buttonLabel}
            savedLabel={settings.savedLabel}
            theme={theme}
          />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[2]}>
          <RecordingShot recording={c.recording} captureSize={c.recordingSize} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[3]}>
          <WordRotate prefix={c.checklistPrefix} words={c.checklist} variant="check" theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[4]}>
          <RingMeter value={done.value} caption={done.caption} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[5]}>
          <EndCard name={c.name} cta={c.cta} url={c.url} theme={theme} />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </VideoThemeProvider>
  );
}

/** Composition settings. The duration is the scenes minus the five 15-frame cuts. */
export const ONBOARDING_FILM = { durationInFrames: 890, fps: 30, width: 1920, height: 1080 } as const;
